    ]
}


def check_file_exists(filepath, description):
    """Check if the file exists."""
    passed = os.path.isfile(filepath)
    message = f"File '{filepath}' exists" if passed else f"File '{filepath}' does not exist"
    return {"check_name": f"{description}_file_exists", "passed": passed, "message": message}


def check_file_not_empty(filepath, description):
    """Check if the file is not empty."""
    if not os.path.isfile(filepath):
        return {"check_name": f"{description}_file_not_empty", "passed": False, 
                "message": f"Cannot check if file '{filepath}' is empty - file does not exist"}

    if os.path.getsize(filepath) == 0:
        return {"check_name": f"{description}_file_not_empty", "passed": False, 
                "message": f"File '{filepath}' is empty"}

    return {"check_name": f"{description}_file_not_empty", "passed": True, 
            "message": f"File '{filepath}' is not empty"}


def check_has_expected_columns(filepath, description):
    """Check if the file has the expected columns."""
    if not os.path.isfile(filepath):
        return {"check_name": f"{description}_has_expected_columns", "passed": False, 
                "message": f"Cannot check columns - file '{filepath}' does not exist"}

    if os.path.getsize(filepath) == 0:
        return {"check_name": f"{description}_has_expected_columns", "passed": False, 
                "message": f"Cannot check columns - file '{filepath}' is empty"}

    expected = EXPECTED_COLUMNS.get(filepath, [])
    if not expected:
        return {"check_name": f"{description}_has_expected_columns", "passed": True, 
                "message": f"No expected columns defined for '{filepath}'"}

    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            actual_columns = set(reader.fieldnames) if reader.fieldnames else set()
            expected_set = set(expected)

            if actual_columns == expected_set:
                return {"check_name": f"{description}_has_expected_columns", "passed": True, 
                        "message": f"File '{filepath}' has all expected columns"}
            else:
                missing = expected_set - actual_columns
                extra = actual_columns - expected_set
                message_parts = []
                if missing:
                    message_parts.append(f"Missing columns: {missing}")
                if extra:
                    message_parts.append(f"Extra columns: {extra}")
                message = f"File '{filepath}' column mismatch: " + ", ".join(message_parts)
                return {"check_name": f"{description}_has_expected_columns", "passed": False, "message": message}
    except Exception as e:
        return {"check_name": f"{description}_has_expected_columns", "passed": False, 
                "message": f"Error reading columns from '{filepath}': {str(e)}"}


