    """Check if the file has data rows (more than just header)."""
    if not os.path.isfile(filepath):
        return {"check_name": f"{description}_has_data_rows", "passed": False, 
                "message": f"Cannot check data rows - file '{filepath}' does not exist"}

    if os.path.getsize(filepath) == 0:
        return {"check_name": f"{description}_has_data_rows", "passed": False, 
                "message": f"Cannot check data rows - file '{filepath}' is empty"}

    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader, None)  # Skip header
            row_count = sum(1 for _ in reader)

            if row_count > 0:
                return {"check_name": f"{description}_has_data_rows", "passed": True, 
                        "message": f"File '{filepath}' has {row_count} data rows"}
            else:
                return {"check_name": f"{description}_has_data_rows", "passed": False, 
                        "message": f"File '{filepath}' has no data rows (only header)"}
    except Exception as e:
        return {"check_name": f"{description}_has_data_rows", "passed": False, 
                "message": f"Error counting rows in '{filepath}': {str(e)}"}


