    """Run all validation checks and return the summary."""
    results = []

    for filepath, file_info in OUTPUT_FILES.items():
        description = file_info["description"]
        checks = file_info["checks"]

        for check_name in checks:
            if check_name == "file_exists":
                results.append(check_file_exists(filepath, description))
            elif check_name == "file_not_empty":
                results.append(check_file_not_empty(filepath, description))
            elif check_name == "has_expected_columns":
                results.append(check_has_expected_columns(filepath, description))
            elif check_name == "has_data_rows":
                results.append(check_has_data_rows(filepath, description))

    return results


def main():
    """Main entry point."""
    # Run validation
    summary = run_validation()

    # Write summary to JSON file
    output_path = "outputs/t14_validation_summary.json"
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(output_path, 'w', encoding='utf-8') as f:
